export function debounce(fn: (...args: any[]) => void, waitMs: number) {
    let timer: ReturnType<typeof setTimeout> | null = null;
    return (...args: any[]) => {
        if (timer !== null) {
            return; // already scheduled
        }
        timer = setTimeout(() => fn(args), waitMs);
        timer = null;
    };
}
```

The bug:
1. The inner function receives `...args` as parameters, but inside the returned function, it uses `fn(args)` — but `args` is the *outer* function's arguments, not the *inner* function's arguments. When you call the debounced function, e.g., `debouncedFn(a, b)`, the `args` captured in the closure refers to the closure scope's `args`, which is the outer function's arguments. Actually, in JavaScript/TypeScript, the `returned function` has its own `args` parameter. But the original code uses `args` from the outer scope — wait, no. Let me think again.

Actually, the original code is:
```typescript
return (...args: any[]) => {
    if (timer !== null) {
        return; // already scheduled
